```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int to;
    int time;
    int cost;
    int next;
} Edge;

typedef struct {
    long long distance;
    int state;
} HeapNode;

typedef struct {
    HeapNode *data;
    int size;
    int capacity;
} MinHeap;

static void heap_push(MinHeap *heap, long long distance, int state) {
    if (heap->size == heap->capacity) {
        heap->capacity = heap->capacity ? heap->capacity * 2 : 1024;
        heap->data = realloc(heap->data, (size_t)heap->capacity * sizeof(HeapNode));
        if (!heap->data) exit(1);
    }

    int i = heap->size++;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap->data[parent].distance <= distance) break;
        heap->data[i] = heap->data[parent];
        i = parent;
    }
    heap->data[i].distance = distance;
    heap->data[i].state = state;
}

static HeapNode heap_pop(MinHeap *heap) {
    HeapNode result = heap->data[0];
    HeapNode last = heap->data[--heap->size];

    if (heap->size > 0) {
        int i = 0;
        while (2 * i + 1 < heap->size) {
            int child = 2 * i + 1;
            if (child + 1 < heap->size &&
                heap->data[child + 1].distance < heap->data[child].distance) {
                child++;
            }
            if (heap->data[child].distance >= last.distance) break;
            heap->data[i] = heap->data[child];
            i = child;
        }
        heap->data[i] = last;
    }

    return result;
}

int main(void) {
    int budget, n, m;
    if (scanf("%d %d %d", &budget, &n, &m) != 3) return 0;

    int *head = malloc((size_t)n * sizeof(int));
    Edge *edges = malloc((size_t)(2 * m) * sizeof(Edge));
    if (!head || !edges) return 0;

    for (int i = 0; i < n; i++) head[i] = -1;

    int edge_count = 0;
    for (int i = 0; i < m; i++) {
        int a, b, time, cost;
        scanf("%d %d %d %d", &a, &b, &time, &cost);
        --a;
        --b;

        edges[edge_count] = (Edge){b, time, cost, head[a]};
        head[a] = edge_count++;
        edges[edge_count] = (Edge){a, time, cost, head[b]};
        head[b] = edge_count++;
    }

    int start, destination;
    scanf("%d %d", &start, &destination);
    --start;
    --destination;

    int costs_per_island = budget + 1;
    int state_count = n * costs_per_island;
    long long *dist = malloc((size_t)state_count * sizeof(long long));
    if (!dist) return 0;

    for (int i = 0; i < state_count; i++) dist[i] = LLONG_MAX;

    MinHeap heap = {NULL, 0, 0};
    int start_state = start * costs_per_island;
    dist[start_state] = 0;
    heap_push(&heap, 0, start_state);

    long long answer = -1;

    while (heap.size > 0) {
        HeapNode current = heap_pop(&heap);
        int state = current.state;

        if (current.distance != dist[state]) continue;

        int island = state / costs_per_island;
        int spent = state % costs_per_island;

        if (island == destination) {
            answer = current.distance;
            break;
        }

        for (int e = head[island]; e != -1; e = edges[e].next) {
            int new_spent = spent + edges[e].cost;
            if (new_spent > budget) continue;

            int next_state = edges[e].to * costs_per_island + new_spent;
            long long new_distance = current.distance + edges[e].time;

            if (new_distance < dist[next_state]) {
                dist[next_state] = new_distance;
                heap_push(&heap, new_distance, next_state);
            }
        }
    }

    printf("%lld\n", answer);

    free(heap.data);
    free(dist);
    free(edges);
    free(head);
    return 0;
}
